-- ============================================================
-- FULL RESET + IMPORT SCRIPT (local DB only)
-- Wipes crm_leads / crm_teachers / crm_teacher_slots and their
-- dependent tables, then re-imports everything from the two
-- cleaned sheets: 503 original leads + 13 new leads found only
-- in the bookings sheet, all 187 bookings applied on top.
-- ============================================================
BEGIN;

-- 1. Wipe existing CRM data
DELETE FROM crm_lead_call_attempts;
DELETE FROM crm_lead_stage_events;
DELETE FROM crm_leads;
DELETE FROM crm_teacher_slots;
DELETE FROM crm_teachers;

